select tablename, indexname, regexp_replace(indexdef,'^.*USING','') d from pg_indexes where schemaname='public' and tablename in ('forge_player_projections','forge_goalie_projections','forge_team_projections','forge_runs','forge_reserve_projections','forge_game_revisions','goalie_start_projections','games','rosters','forge_player_game_strength','rolling_player_game_metrics','lineCombinations','pbp_games','shift_charts') order by 1,2
